export function makePartnerBadgeSvg(text: string, sub = '', isLightBg = false): string {
  const bg = isLightBg ? '#FFFFFF' : '#071426';
  const titleCol = isLightBg ? '#071426' : '#E8CC7D';
  const subCol = isLightBg ? '#9A7413' : '#CBD5E1';
  const borderCol = '#C59B27';
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="240" height="86" viewBox="0 0 240 86">
    <rect width="240" height="86" rx="12" fill="${bg}"/>
    <rect x="3" y="3" width="234" height="80" rx="10" fill="none" stroke="${borderCol}" stroke-opacity="0.55" stroke-width="1.5"/>
    <text x="120" y="${sub ? '40' : '49'}" text-anchor="middle" fill="${titleCol}" font-family="Plus Jakarta Sans, Tajawal, sans-serif" font-weight="800" font-size="16" letter-spacing="0.5">${text}</text>
    ${sub ? `<text x="120" y="62" text-anchor="middle" fill="${subCol}" font-family="Tajawal, Plus Jakarta Sans, sans-serif" font-weight="700" font-size="11.5">${sub}</text>` : ''}
  </svg>`;
  return 'data:image/svg+xml;utf8,' + encodeURIComponent(svg);
}

